-- Candidates/db/seed/precinct_polygons_laramie_seed.sql
-- Laramie County current precinct polygons from CLK ArcGIS FeatureServer (live, post-redistricting).
-- Vote center model: any voter may use any of the 12 vote centers.
-- Precincts assigned to geographically nearest center. Source: maps.clcgisc.com
-- Replaces 2020 Census TIGER VTD data (61 rows → current 42 rows).

DELETE FROM precinct_polygons WHERE LOWER(county) = 'laramie';

